python3 -c "
import json, os
logdir = 'logdir/exp_058_frozen_dt_emb_cheetah_s1'
mf = os.path.join('/root/autodl-tmp/event-gated-adaptive-horizon', logdir, 'metrics.jsonl')

all_keys = set()
ve_keys = set()
lines = []
with open(mf) as f:
    for line in f:
        m = json.loads(line)
        lines.append(m)
        for k in m.keys():
            all_keys.add(k)
            if 've_ratio' in k or 'civo' in k or 've_' in k:
                ve_keys.add(k)

print(f'Total unique keys: {len(all_keys)}')
print(f'VE-related keys: {ve_keys}')
print(f'All keys: {sorted(all_keys)}')

for key in ve_keys:
    print(f'\n--- Data for key: {key} ---')
    data = {}
    for m in lines:
        step = m.get('step', 0)
        if key in m and step % 10000 <= 2500:
            data[step] = round(m[key], 4)
    for s, v in sorted(data.items()):
        print(f'  {s}: {v}')
    if data:
        peak_s, peak_v = max(data.items(), key=lambda x: x[1])
        final_s, final_v = sorted(data.items())[-1]
        print(f'  PEAK: {peak_v} @ {peak_s}')
        print(f'  FINAL: {final_v} @ {final_s}')

if not ve_keys:
    print('\nNO VE KEYS FOUND. First 3 lines:')
    for i in range(min(3, len(lines))):
        print(json.dumps(lines[i], indent=2))
    print('\nLast 3 lines:')
    for i in range(max(0, len(lines)-3), len(lines)):
        print(json.dumps(lines[i], indent=2))
"
